import random, sys
sys.setrecursionlimit(100000)
from sheet import evaluate, CycleError

# Independent naive reference: recursive, re-evaluates, separate code path.
def ref_eval(cells):
    def val(name, seen):
        if name in seen:
            raise CycleError(name)
        toks, i = cells[name].strip(), 0
        s = toks[1:] if toks.startswith("=") else toks
        # eval via python after substituting refs, using true division
        out, j = "", 0
        while j < len(s):
            c = s[j]
            if c.isalpha():
                k = j
                while k < len(s) and (s[k].isalpha() or (s[k].isdigit() and k > j)):
                    k += 1
                out += "(" + repr(val(s[j:k], seen | {name})) + ")"
                j = k
            else:
                out += c
                j += 1
        return float(eval(out or "0"))
    return {n: val(n, frozenset()) for n in cells}

random.seed(1234)
names = ["A", "B", "C", "D", "E", "F1", "G2", "TOT"]
checked = cyc = zde = 0
for trial in range(4000):
    cells = {}
    for n in names:
        if random.random() < 0.3:
            cells[n] = str(random.choice([0, 1, 2, 3, 7, 0.5, 2.25]))
        else:
            def expr(depth=0):
                r = random.random()
                if depth > 2 or r < 0.35:
                    return random.choice(names + ["1", "2", "3", "0", "4.5"])
                if r < 0.45:
                    return "-" + expr(depth + 1)
                if r < 0.60:
                    return "(" + expr(depth + 1) + ")"
                return expr(depth + 1) + random.choice("+-*/") + expr(depth + 1)
            cells[n] = "=" + expr()
    def run(f):
        try:
            return ("ok", f(cells))
        except CycleError:
            return ("cycle", None)
        except ZeroDivisionError:
            return ("zde", None)
    mine, theirs = run(evaluate), run(ref_eval)
    # Reference may hit ZeroDivisionError before finding a cycle (evaluation
    # order differs), so only compare when both agree on reaching a value.
    if mine[0] == "ok" and theirs[0] == "ok":
        assert mine[1] == theirs[1], (cells, mine[1], theirs[1])
        checked += 1
    elif mine[0] == "cycle":
        assert theirs[0] in ("cycle", "zde"), (cells, mine, theirs)
        cyc += 1
    elif mine[0] == "zde":
        assert theirs[0] in ("zde", "cycle"), (cells, mine, theirs)
        zde += 1
print("values matched:", checked, "| cycles:", cyc, "| div-by-zero:", zde)
